    for (var k = 0; k < 9; k++) s += '<ellipse class="marrow" cx="' + f1(x0 + 22 + ((k * 61) % (x1 - x0 - 40))) + '" cy="' + f1(B + 36 + ((k * 23) % 90)) + '" rx="' + (7 + (k % 3) * 2) + '" ry="5"/>';
