  [xb, xa].concat(fixd ? [xp] : []).forEach(function (x) { o += '<path class="ti-hi" d="M' + (x - 14) + " " + B + "L" + (x + 14) + " " + B + "L" + (x + 18) + " " + (B - 26) + "L" + (x - 18) + " " + (B - 26) + 'Z"/>'; });
