  o += '<path class="axis" d="M' + X0 + " " + Y1 + "V" + Y0 + "H" + X1 + '"/>';
  for (var w = 0; w <= 12; w += 2) o += '<path class="grid" d="M' + f1(X(w)) + " " + Y1 + "V" + Y0 + '"/>' + T(X(w), Y0 + 16, String(w), "s mut", "middle");
