  function prof(off) { var d = "", k2; for (k2 = 0; k2 < 5; k2++) { var y = iy + 8 + k2 * 38; d += "L" + f1(ix + off) + " " + y + "L" + f1(tx + off) + " " + (y + 10) + "L" + f1(tx + off) + " " + (y + 18) + "L" + f1(ix + off) + " " + (y + 28); } return d; }
